#[derive(Debug)]
pub struct ActionSummary<'a> {
    pub action_type: &'static str,
    pub id: Option<&'a str>,
    pub text_len: Option<usize>,
    pub submit: Option<bool>,
    pub value_len: Option<usize>,
    pub url: Option<&'a str>,
    pub scroll: Option<(i64, i64)>,
    pub wait_ms: Option<u64>,
    pub query_len: Option<usize>,
    pub summary_len: Option<usize>,
}

impl<'a> From<&'a Action> for ActionSummary<'a> {
    fn from(action: &'a Action) -> Self {
        match action {
            Action::Click { id } => ActionSummary {
                action_type: "click",
                id: Some(id.as_str()),
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Type { id, text, submit } => ActionSummary {
                action_type: "type",
                id: Some(id.as_str()),
                text_len: Some(text.chars().count()),
                submit: *submit,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Select { id, value } => ActionSummary {
                action_type: "select",
                id: Some(id.as_str()),
                text_len: None,
                submit: None,
                value_len: Some(value.chars().count()),
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Scroll { dx, dy } => ActionSummary {
                action_type: "scroll",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: Some((*dx, *dy)),
                wait_ms: None,
